package com.ethk3.novaonepro.strategyv2;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
/** Read-only assessment of the captured database; no score or recommendation grants authority. */
public final class StrategyAssessmentR26 {
 private StrategyAssessmentR26(){}
 private static final int LIMIT=64;
 static JSONObject repair(String reason)throws JSONException{
  String action,hypothesis,falsifier;
  switch(reason){
   case "CALENDAR_INCOMPLETE":case "BENCHMARK_CALENDAR_INCOMPLETE":case "EVIDENCE_INTEGRITY_ERROR":action="REPAIR_FREEZE_SETTLEMENT_AND_PAIRED_CALENDAR";hypothesis="Missing or inconsistent source evidence can bias apparent quality";falsifier="Every preregistered ordinal has one timely freeze and terminal result, including the benchmark";break;
   case "PENDING_LABELS":action="WAIT_FOR_TERMINAL_OWNER_AND_RESUME_FOLD";hypothesis="Unsettled labels prevent a complete evaluation";falsifier="Terminal settlement and the evidence cursor reach the registered endpoint";break;
   case "COVERAGE_LT_0.15":action="RESEARCH_GATE_COVERAGE_FRONTIER_ON_FROZEN_HISTORY";hypothesis="A selective gate may trade coverage for apparent hit rate";falsifier="A new preregistered policy preserves coverage and passes independent future evidence";break;
   case "OBSERVED_HIT_RATE_LT_035":action="RESEARCH_FAILURE_CLUSTERS_AND_MATCHED_COST_CHILDREN";hypothesis="The observed mechanism may lack predictive gain";falsifier="A preregistered child beats matched controls on independent future labels";break;
   case "BLOCK_BELOW_FLOOR":action="RESEARCH_REGIME_ROBUSTNESS_AND_PATH_ABLATIONS";hypothesis="Performance may depend on one favorable segment";falsifier="All preregistered blocks preserve the stability floor without selecting favorable dates";break;
   case "PAIRED_LCB_BELOW_PREREGISTERED_MINUS_001":action="RESEARCH_COMPLEMENTARY_CHILD_WITH_SAME_ISSUE_BASELINE";hypothesis="The child may not improve its matched incumbent";falsifier="The original paired lower-bound test passes at an allocated look";break;
   case "CALIBRATION_FAILED":case "CALIBRATION_INSUFFICIENT":case "HELD_LATER_ECE_GT_004":action="FIT_ON_EARLIER_DATA_VALIDATE_CALIBRATION_ON_LATER_DATA";hypothesis="Selected action probabilities may be overconfident";falsifier="Preregistered held-later ECE/Brier and coverage criteria pass";break;
   case "PASS":action="CONTINUE_PREREGISTERED_MONITORING_AND_CHECK_CURRENT_AUTHORITY";hypothesis="A recorded passing check may become stale or be revoked";falsifier="The runtime authority owner independently validates the current policy and certificate";break;
   default:action="COLLECT_PREREGISTERED_FUTURE_EVIDENCE_WITHOUT_RESETTING_BIRTH";hypothesis="Evidence may be too short or too uncertain to distinguish gain from chance";falsifier="The existing allocated calendar look, sample, coverage and lower-bound tests pass";
  }
  return new JSONObject().put("reason",reason).put("action",action).put("hypothesis",hypothesis).put("falsifier",falsifier).put("executionState","RECOMMENDATION_NOT_AN_EXECUTED_EXPERIMENT").put("newResearchPolicyRequiresNewBirth",true);
 }
 private static JSONObject observation(SQLiteDatabase db,String policy,long birth)throws Exception{
  EvidenceBlockR26 total=new EvidenceBlockR26();JSONArray blocks=new JSONArray();long from=-1,end=-1,through=birth-1;EvidenceBlockR26 partial=new EvidenceBlockR26();boolean cursorPresent=false;
  try(Cursor c=db.rawQuery("SELECT protocol,through_ordinal,partial FROM r26_evidence_cursor WHERE policy_hash=?",new String[]{policy})){if(c.moveToFirst()){cursorPresent=true;if(!QualificationWindowR26.PROTOCOL.equals(c.getString(0)))throw new IllegalStateException("ASSESSMENT_PROTOCOL");through=c.getLong(1);partial=EvidenceBlockR26.read(c.getBlob(2));if(through<birth-1||partial.calendar>=EvidenceAccumulatorR26.BLOCK)throw new IllegalStateException("ASSESSMENT_CURSOR");}}
  try(Cursor c=db.rawQuery("SELECT from_ordinal,to_ordinal,statistics FROM r26_evidence_block WHERE policy_hash=? ORDER BY block_index LIMIT 122",new String[]{policy})){while(c.moveToNext()){
   if(blocks.length()>=121)throw new IllegalStateException("ASSESSMENT_RETENTION_BOUND");long a=c.getLong(0),b=c.getLong(1);EvidenceBlockR26 item=EvidenceBlockR26.read(c.getBlob(2));if(a<birth||b-a!=EvidenceAccumulatorR26.BLOCK||item.calendar!=b-a||end>=0&&a!=end)throw new IllegalStateException("ASSESSMENT_BLOCK_CONTINUITY");if(from<0)from=a;end=b;total.merge(item);blocks.put(new JSONObject().put("fromOrdinal",a).put("toExclusive",b).put("acts",item.acts).put("hits",item.hits).put("hitRate",item.acts==0?JSONObject.NULL:item.hits/(double)item.acts).put("missing",item.missing));
  }}
  if(!cursorPresent&&blocks.length()>0)throw new IllegalStateException("ASSESSMENT_MISSING_CURSOR");long partialFrom=through-partial.calendar+1;if(partialFrom<birth||end>=0&&partialFrom!=end||end<0&&partialFrom!=birth)throw new IllegalStateException("ASSESSMENT_PARTIAL_CONTINUITY");if(from<0&&partial.calendar>0)from=partialFrom;if(partial.calendar>0)total.merge(partial);if(end<0)end=birth;if(total.calendar>0)end=through+1;
  double worst=1;int measured=0;for(int i=0;i<blocks.length();i++){JSONObject b=blocks.getJSONObject(i);if(b.getLong("acts")>0){worst=Math.min(worst,b.getDouble("hitRate"));measured++;}}
  double brier=0;for(int i=0;i<EvidenceBlockR26.BINS;i++){double p=EvidenceBlockR26.representative(i);brier+=total.count[i]*p*p-2*total.won[i]*p+total.won[i];}
  return new JSONObject().put("scope","RETAINED_POST_BIRTH_FROZEN_SETTLED_CALENDAR_FOLDS; DESCRIPTIVE_NOT_A_QUALIFICATION_WINDOW").put("sourceAudit","PERSISTED_FOLD_SHAPE_CHECKED; FULL_SOURCE_CHAIN_NOT_REAUDITED_BY_REPORT").put("fromOrdinal",from<0?JSONObject.NULL:from).put("toExclusive",total.calendar==0?JSONObject.NULL:end).put("calendarOpportunities",total.calendar).put("acts",total.acts).put("hits",total.hits).put("hitRate",total.acts==0?JSONObject.NULL:total.hits/(double)total.acts).put("coverage",total.calendar==0?JSONObject.NULL:total.acts/(double)total.calendar).put("missing",total.missing).put("pending",total.pending).put("benchmarkMissing",total.benchmarkMissing).put("worstRetained720BlockRate",measured==0?JSONObject.NULL:worst).put("measuredBlocks",measured).put("blocks",blocks).put("rawQuantizedBrier",total.acts==0?JSONObject.NULL:brier/total.acts).put("brierDefinition","ACT-only Brier using the persisted256-bin probability representative; not held-later calibrated Brier").put("uncertainty","Use the separately recorded allocated fixed-window lower bound; descriptive rates do not establish quality");
 }
 public static JSONObject snapshot(SQLiteDatabase db)throws JSONException{
  JSONObject root=new JSONObject().put("schema","R26_STRATEGY_ASSESSMENT_1").put("authorityGranted",false).put("scope","CAPTURED_DATABASE_EVIDENCE; NO_GUARANTEE_OF_HIGH_HIT_RATE_OR_MONOTONIC_EVOLUTION").put("requiredCalendarOpportunities",QualificationWindowR26.LENGTH).put("independentOpportunityUnit","ONE_SCHEDULED_ISSUE_NOT_100_CELLS_OR_1200_ACTIONS");JSONArray policies=new JSONArray();long total=0;
  try(Cursor c=db.rawQuery("SELECT count(*) FROM r26_live_model",null)){if(c.moveToFirst())total=c.getLong(0);}
  try(Cursor c=db.rawQuery("SELECT l.policy_hash,l.family_id,l.status,l.born_ordinal,q.protocol,q.family_alpha,l.canonical_text FROM r26_live_model l LEFT JOIN r26_cohort q ON q.genome_key=l.policy_hash ORDER BY l.updated_at DESC,l.policy_hash LIMIT 64",null)){while(c.moveToNext()){
   String policy=c.getString(0),reason="NO_COMPLETED_PREREGISTERED_LOOK";long birth=c.getLong(3);JSONObject row=new JSONObject().put("policyHash",policy).put("family",c.getString(1)).put("runtimeStatus",c.getString(2)).put("bornOrdinal",birth).put("canonicalPolicy",c.getString(6)).put("implementation",FamilyRegistryR26.implementation(c.getString(1))).put("qualification",JSONObject.NULL).put("formalLowerBound",JSONObject.NULL).put("authorityGranted",false);
   try{if(c.isNull(4)||!QualificationWindowR26.PROTOCOL.equals(c.getString(4)))throw new IllegalStateException("ASSESSMENT_COHORT_PROTOCOL");JSONObject observed=observation(db,policy,birth);row.put("observed",observed);if(observed.getInt("missing")>0)reason="CALENDAR_INCOMPLETE";else if(observed.getInt("pending")>0)reason="PENDING_LABELS";
    try(Cursor q=db.rawQuery("SELECT window_start,window_end,look,acts,hits,rate,lower_bound,coverage,worst_block,paired_lower,ece,reason,checked_at,evidence_digest FROM r26_qualification_result WHERE policy_hash=?",new String[]{policy})){if(q.moveToFirst()){
     long a=q.getLong(0),b=q.getLong(1),n=q.getLong(3),wins=q.getLong(4);int look=q.getInt(2);double rate=q.getDouble(5),lower=q.getDouble(6),coverage=q.getDouble(7),worst=q.getDouble(8);
     if(a<birth||b-a!=QualificationWindowR26.LENGTH||(a-birth)%QualificationWindowR26.STRIDE!=0||look!=(a-birth)/QualificationWindowR26.STRIDE+1||observed.isNull("toExclusive")||b>observed.getLong("toExclusive")||n<0||n>QualificationWindowR26.LENGTH||wins<0||wins>n||!Double.isFinite(rate)||!Double.isFinite(lower)||!Double.isFinite(coverage)||!Double.isFinite(worst)||lower<0||lower>rate||rate>1||Math.abs(rate-(n==0?0:wins/(double)n))>1e-10||coverage<0||coverage>1||Math.abs(coverage-n/(double)QualificationWindowR26.LENGTH)>1e-10||worst<0||worst>1)throw new IllegalStateException("ASSESSMENT_QUALIFICATION_SHAPE");
     if("PASS".equals(q.getString(11))&&(n<600||coverage<.15||rate<.35||lower<=.30||worst<.28||q.isNull(9)||!Double.isFinite(q.getDouble(9))||q.getDouble(9)<-.01||q.isNull(10)||!Double.isFinite(q.getDouble(10))||q.getDouble(10)>.04))throw new IllegalStateException("ASSESSMENT_INCONSISTENT_RECORDED_PASS");
     JSONObject last=new JSONObject();for(int i=0;i<q.getColumnCount();i++)last.put(q.getColumnName(i),q.isNull(i)?JSONObject.NULL:q.getType(i)==Cursor.FIELD_TYPE_INTEGER?q.getLong(i):q.getType(i)==Cursor.FIELD_TYPE_FLOAT?q.getDouble(i):q.getString(i));last.put("scope","LAST_PERSISTED_FIXED_WINDOW_CHECK; NOT_CURRENT_AUTHORITY_OR_LATEST_OBSERVATION");row.put("qualification",last).put("formalLowerBound",q.getDouble(6));if(reason.equals("NO_COMPLETED_PREREGISTERED_LOOK"))reason=q.getString(11);
     if(!c.isNull(5)&&q.getInt(2)>0)last.put("allocatedAlpha",SelectiveEvidenceSU2.alphaForLook(c.getDouble(5),q.getInt(2)));row.put("qualificationReasonIsPass","PASS".equals(q.getString(11)));
    }}
    long accumulated=observed.isNull("toExclusive")?0:Math.max(0,observed.getLong("toExclusive")-birth);row.put("calendarPositionsSinceBirth",accumulated).put("positionsUntilFirstLook",Math.max(0,QualificationWindowR26.LENGTH-accumulated));
   }catch(Exception bad){row.put("observed",JSONObject.NULL).put("qualification",JSONObject.NULL).put("formalLowerBound",JSONObject.NULL).put("evidenceError",bad.toString());reason="EVIDENCE_INTEGRITY_ERROR";}
   JSONArray lineage=new JSONArray();try(Cursor e=db.rawQuery("SELECT parent,operation,category,research_accepted,behavior_novel,prospective_qualified,verified_improvement FROM r26_evolution WHERE policy_hash=? ORDER BY attempt_id LIMIT 64",new String[]{policy})){while(e.moveToNext()){JSONObject record=new JSONObject();for(int i=0;i<e.getColumnCount();i++)record.put(e.getColumnName(i),e.isNull(i)?JSONObject.NULL:e.getType(i)==Cursor.FIELD_TYPE_INTEGER?e.getLong(i):e.getString(i));lineage.put(record);}}row.put("lineage",lineage).put("lineageScope","At most64 retained ledger assertions ordered by attempt id; not independent evidence of generational improvement");
   row.put("assessmentReason",reason).put("nextResearch",repair(reason));policies.put(row);
  }}
  JSONObject evolution=new JSONObject();try(Cursor c=db.rawQuery("SELECT count(*) attempts,coalesce(sum(category='STRUCTURAL_CANDIDATE'),0) structural,coalesce(sum(research_accepted),0) researchAccepted,coalesce(sum(prospective_qualified),0) qualificationAssertions,coalesce(sum(verified_improvement),0) improvementAssertions FROM r26_evolution",null)){if(c.moveToFirst())for(int i=0;i<c.getColumnCount();i++)evolution.put(c.getColumnName(i),c.getLong(i));}evolution.put("scope","PERSISTED_LEDGER_ASSERTIONS_ACROSS_RETAINED_SOURCES; NO_NEW_REAUDIT_OR_PER_GENERATION_GAIN_INFERRED");
  return root.put("policies",policies).put("totalPolicies",total).put("exportedPolicies",policies.length()).put("omittedPolicies",Math.max(0,total-policies.length())).put("evolution",evolution).put("absenceOfPolicies","No deployable quality can be inferred from trained candidates or an empty report");
 }
}
